head.script:
// 테스트 설명, 유효성 값 설정
//  - 'Body Column 에서만 동작하며 다른 영역의 Column 에 설정 시 무시됩니다.' 는 Body 전용 방침에 따라 제외
//  - embeddedInput='true' 조건과 inputType='custom'(typeGetter) 조건은 column_P_escapeFormatter_2.xml 에서 검증
scwin.tData = {
    "description" : "[column > P > escapeFormatter]<br/>Column 의 표시값에 포함된 특수문자를 이스케이프 처리하는 사용자 정의 함수를 설정합니다.",
    "validation" : [
        "inputType='text', escape='false', embeddedInput='false' 인 경우에 동작하며, inputType='link' 이면 escapeFormatterOrder 속성을 설정해야 동작합니다.",
        "함수 이름 설정 시, 사용자 정의 함수의 파라미터로 Cell 값 또는 표시값, Row 인덱스, Column 인덱스 값이 전달됩니다.",
        "escapeFormatterOrder 속성을 설정하지 않았거나 'first' 이면 첫번째 파라미터로 원본 Column 값이 전달됩니다.",
        "escapeFormatterOrder='last' 이면 displayFormat, customFormatter 등이 적용된 표시값이 첫번째 파라미터로 전달됩니다.",
        "함수 이름 설정 시, 사용자 정의 함수의 반환값이 Column 에 표시되는 값으로 적용됩니다.",
        "'<script>' 태그처럼 보안상 문제가 될 수 있는 값을 직접 제어하기 위해 escapeFormatter 속성을 설정합니다.",
        "사용자 정의 함수의 반환값은 Cell 값 표시에만 사용되며 DataList 에는 반영되지 않습니다.",
        "Column 의 inputType='text' 이고 escape='true' 인 경우 escapeFormatterOrder='last' 이면 escapeFormatter 속성이 동작합니다.",
        "이때, escape 속성은 사용자 정의 함수가 실행되기 전에 적용되며, 사용자 정의 함수의 반환값에는 이스케이프 처리를 하지 않습니다.",
        "단, maskFormat 과 displayFormat 을 함께 설정한 경우에는 사용자 정의 함수의 반환값이 이스케이프 처리되어 표시됩니다.",
        "Column 의 inputType='link' 인 경우 escape='true' 이면 사용자 정의 함수의 반환값이 이스케이프 처리됩니다.",
        "getCellDisplayData() 등 Display 포맷이 적용된 데이터를 반환하는 메소드와 advancedExcelDownload() 메소드의 Display 데이터에도 사용자 정의 함수가 적용됩니다."
    ]
}



scwin.gVar = {
    // escapeFormatter 사용자 함수에 Row 인덱스별로 전달된 파라미터 (Target 생성 시 초기화)
    "escapeParams" : {},
    // 사용자 함수 파라미터 기록 여부 (getCellDisplayData 호출 중에는 기록하지 않는다)
    "recording" : true
}



scwin.onpageload = async function () {
    // Global DataList(gdl_boolean 등) 생성 호출
    $c.gcm.createCommonDatalist();

    // 정적 select1 은 초기 selectedIndex 가 적용되지 않으므로 기본값 명시 설정
    //  gdl_boolean 코드값 : 미설정='1' / true='2' / false='3'
    con_inputType.setValue("text");
    con_escape.setValue("3");
    con_escapeFormatterOrder.setValue("");
    con_customFormatter.setValue("");
    con_displayFormat.setValue("");
    con_maskFormat.setValue("");

    // comp 초기 생성
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// escapeFormatter 로 지정하는 사용자 함수 : script 태그를 제거하고 밑줄(u 태그)로 감싸 반환
scwin.fmtEscape = function (data, rowIndex, colIndex) {
    if (scwin.gVar.recording) {
        scwin.gVar.escapeParams[rowIndex] = { "data" : data, "colIndex" : colIndex };
    }
    let reScript = new RegExp("<script.*?</scr" + "ipt>", "gi");
    return "<u>" + String(data).replace(reScript, "") + "</u>";
}



// customFormatter 로 지정하는 사용자 함수 : 두 번째 파라미터(표시값) 앞에 ★ 를 붙여 반환
scwin.fmtStar = function (data, formattedData, rowIndex, colIndex) {
    return "★ " + formattedData;
}



// comp 생성
//  escapeFormatter 관련 속성은 렌더 시 결정되므로 con 변경 후 Target 재생성(btn_createTarget -> comp_init) 으로만 반영한다.
scwin.comp_init = async function () {
    // 기존 target / dataList / label 삭제
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove("dlt_bind");
    }
    if (typeof label1 !== 'undefined' && label1) {
        label1.remove();
    }
    scwin.gVar.escapeParams = {};
    scwin.gVar.recording = true;

    // 테스트 정보 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] escapeFormatter=scwin.fmtEscape 고정 (script 태그 제거 후 u 태그로 감싸 반환), customFormatter 함수는 표시값 앞에 ★ 추가\n[전제] Row 0 은 script, b 태그 포함, Row 1 은 < > & 문자, Row 2 는 숫자 11자리\n[절차] 조건 선택 -> Target 재생성 -> 셀 표시값 확인 / advancedExcelDownload 클릭\n[확인] DataList 값 -> 첫번째 파라미터 -> 셀 표시값(해석된 태그) -> getCellDisplayData 반환값, 다운로드된 Excel 파일의 Cell 값"', '', 'label1');

    // 조건 (gdl_boolean 은 getText 로 라벨('' / 'true' / 'false') 을 읽는다)
    let cInputType = con_inputType.getValue();
    let cEscape = con_escape.getText();
    let cEscapeFormatterOrder = con_escapeFormatterOrder.getValue();
    let cCustomFormatter = con_customFormatter.getValue();
    let cDisplayFormat = con_displayFormat.getValue();
    let cMaskFormat = con_maskFormat.getValue();

    // dataList 생성 (특수문자 포함 값은 setJSON 으로 주입)
    let strNameSpace = $c.gcm.getNameSpace();
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="val" name="val" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);
    dlt_bind.setJSON([
        { "val" : "<script>alert('XSS')</scr" + "ipt><b>긴급</b> 반품 요청" },
        { "val" : "재고 5 < 10 & 단가 > 0" },
        { "val" : "01012345678" }
    ], false);

    // val Column 속성 (미설정 옵션은 속성 자체를 넣지 않는다)
    let attrVal = ' inputType="' + cInputType + '" escapeFormatter="scwin.fmtEscape"';
    if (cEscape !== '') {
        attrVal += ' escape="' + cEscape + '"';
    }
    if (cEscapeFormatterOrder !== '') {
        attrVal += ' escapeFormatterOrder="' + cEscapeFormatterOrder + '"';
    }
    if (cCustomFormatter !== '') {
        attrVal += ' customFormatter="' + cCustomFormatter + '"';
    }
    if (cDisplayFormat !== '') {
        attrVal += ' displayFormat="' + cDisplayFormat + '"';
    }
    if (cMaskFormat !== '') {
        attrVal += ' maskFormat="' + cMaskFormat + '"';
    }

    let headerText = "val (" + cInputType + " / escape " + (cEscape === '' ? "미설정" : cEscape) + " / escapeFormatterOrder " + (cEscapeFormatterOrder === '' ? "미설정" : cEscapeFormatterOrder) + ")";

    // target 생성
    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_bind" checkAllType="false" id="" style="width:700px;height:150px;">';
    strTarget += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="680" style="" inputType="text" id="column1" value="' + headerText + '"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="680" style="" id="val" value=""' + attrVal + '></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin["target1"] = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// val 셀의 화면 표시값과 해석된 태그
//  - 표시 영역(link 는 a 태그 안, 그 외 nobr / textarea 영역) 안에 HTML 요소가 생성되어 있으면 (태그 해석 : 태그명) 표기
scwin.getCellStr = function (rowIndex) {
    let td = document.querySelector("td[id*='" + target1.id + "_cell_" + rowIndex + "_0']");
    if (!td) {
        return "Cell 없음";
    }
    let wrap = td.querySelector("a") || td.querySelector("nobr, span.w2grid_span, div.w2grid_textarea") || td;
    let str = "'" + wrap.textContent + "'";
    let tags = [];
    let elems = wrap.querySelectorAll("*");
    for (let i = 0; i < elems.length; i++) {
        let tagName = elems[i].tagName.toLowerCase();
        if (tags.indexOf(tagName) < 0) {
            tags.push(tagName);
        }
    }
    if (tags.length > 0) {
        str += "(태그 해석 : " + tags.join(", ") + ")";
    }
    return str;
}



// 전체 Row 의 DataList 값 -> 첫번째 파라미터 -> 셀 표시값 -> getCellDisplayData 반환값 출력
//  - validation 1, 8, 11 : 조건별 사용자 함수 호출 여부(호출 안 됨)와 반환값(u 태그)의 해석 여부
//  - validation 2, 3, 4 : 첫번째 파라미터(원본값 / 표시값)와 Column 인덱스
//  - validation 5, 6 : 셀 표시값이 반환값(script 태그 제거, u 태그)으로 적용되는지
//  - validation 7 : DataList 값이 원본 그대로인지
//  - validation 9, 10 : escape='true' 일 때 첫번째 파라미터가 이스케이프된 값인지, 반환값(u 태그)이 해석되는지
//  - validation 12 : getCellDisplayData 반환값에 사용자 함수 반환값이 적용되는지
scwin.btn_checkCell_onclick = function () {
    let bottom = wf_body_bottom.getObj("scwin");
    let arrLine = [];
    for (let i = 0; i < dlt_bind.getRowCount(); i++) {
        let param = scwin.gVar.escapeParams[i];
        let arrText = ["Row " + i + " '" + dlt_bind.getCellData(i, "val") + "'"];
        arrText.push("첫번째 파라미터 " + (typeof param === "undefined" ? "호출 안 됨" : "'" + param.data + "' (Column 인덱스 " + param.colIndex + ")"));
        arrText.push(scwin.getCellStr(i));
        arrLine.push(arrText);
    }
    // getCellDisplayData 도 사용자 함수를 호출하므로 셀 렌더링 때 기록한 파라미터를 덮어쓰지 않도록 기록을 멈춘다.
    scwin.gVar.recording = false;
    for (let i = 0; i < arrLine.length; i++) {
        arrLine[i].push("getCellDisplayData '" + target1.getCellDisplayData(i, "val") + "'");
        bottom.setReturnValue(arrLine[i].join(" -> "));
    }
    scwin.gVar.recording = true;
}



// advancedExcelDownload 실행 : 다운로드된 Excel 파일의 val Cell 값(Display 데이터)으로 사용자 함수 적용 여부를 확인 (validation 12)
scwin.btn_advancedExcelDownload_onclick = function () {
    scwin.gVar.recording = false;
    try {
        target1.advancedExcelDownload({ "fileName" : "column_escapeFormatter.xlsx" });
    } finally {
        scwin.gVar.recording = true;
    }
}
